static void CheckException(bool allocation){auto snapshot=std::make_shared<const DecodedPcm>(Pcm(2));Coordinator c([allocation](const DecodedPcm&,std::string*)->std::shared_ptr<const PeakCache>{if(allocation)throw std::bad_alloc();throw std::runtime_error("test");});c.Begin(snapshot,1);CHECK(c.WaitForCompletion(1,kTimeout));CHECK(c.Apply(1));CHECK(c.Status()==BuildState::Failed);CHECK(!c.Cache());CHECK(!c.Diagnostic().empty());}
static bool Ordered(const std::vector<RulerTick>& ticks,uint32_t width,const Viewport& v){uint64_t previous=v.start;for(const auto&t:ticks){if(t.frame<previous||t.frame<v.start||t.frame>=v.end||t.x<0||t.x>width||t.label.empty())return false;previous=t.frame;}return true;}
