  DecodedPcm empty{1,48000,0,{}};CHECK(BuildPeakCache(empty));DecodedPcm invalid{2,1,std::numeric_limits<uint64_t>::max(),{}};CHECK(!BuildPeakCache(invalid));DecodedPcm nan{1,1,1,{NAN}};CHECK(!BuildPeakCache(nan));
  // Viewport, resolution clamp and coordinate matrix.
  auto cache=BuildPeakCache(Pcm(1000),64);CHECK(MinimumViewportSpan(*cache)==64);CHECK(MinimumViewportSpan(*BuildPeakCache(Pcm(32),64))==32);auto full=FullViewport(1000);CHECK(full.start==0&&full.end==1000);auto zoom=Zoom(full,100,.25,MinimumViewportSpan(*cache));CHECK(zoom.end-zoom.start>=64);auto pointerBefore=XToFrame(full,250,1000),pointerAfter=XToFrame(zoom,250,1000);CHECK(std::llabs(static_cast<long long>(pointerBefore-pointerAfter))<=2);auto zoomedOut=Zoom(zoom,.001,.5,64);CHECK(zoomedOut.start==full.start&&zoomedOut.end==full.end);CHECK(Scroll(zoom,INT64_MIN).start==0);CHECK(Scroll(zoom,INT64_MAX).end==1000);auto same=Scroll(full,1);CHECK(same.start==full.start&&same.end==full.end);CHECK(FrameToX(full,0,500)==0&&FrameToX(full,1000,500)==500);CHECK(XToFrame(full,0,500)==0&&XToFrame(full,500,500)==1000);CHECK(XToFrame(full,-1,500)==0&&XToFrame(full,900,500)==1000&&XToFrame(full,NAN,500)==0);auto huge=FullViewport(UINT64_MAX);CHECK(FrameToX(huge,0,800)==0&&XToFrame(huge,0,800)==0);const Viewport beyondFloat{UINT64_MAX,UINT64_C(1)<<62,UINT64_MAX};const auto midpoint=XToFrame(beyondFloat,400.,800.);CHECK(midpoint>UINT64_C(1)<<62&&FrameToX(beyondFloat,midpoint,800.)>399.&&FrameToX(beyondFloat,midpoint,800.)<401.);
  // Render plans retain channels/extrema and only inspect the narrow visible range.
