  CHECK(SelectUiState(AudioDocumentState::Loading,BuildState::Ready)==UiState::AudioLoading);CHECK(SelectUiState(AudioDocumentState::Ready,BuildState::Building)==UiState::WaveformBuilding);CHECK(SelectUiState(AudioDocumentState::Ready,BuildState::Failed)==UiState::WaveformFailed);CHECK(SelectUiState(AudioDocumentState::Ready,BuildState::Ready)==UiState::Ready);
  // Submission keeps the same PCM object and backing vector; exceptions are delivered without terminating the process.
  auto snapshot=std::make_shared<const DecodedPcm>(Pcm(3));const auto* address=snapshot.get();const auto* data=snapshot->interleaved.data();std::promise<void> received;auto seen=received.get_future();Coordinator noCopy([&](const DecodedPcm& p,std::string* e){CHECK(&p==address&&p.interleaved.data()==data);received.set_value();return BuildPeakCache(p,64,e);});noCopy.Begin(snapshot,1);CHECK(seen.wait_for(kTimeout)==std::future_status::ready);CHECK(noCopy.WaitForCompletion(1,kTimeout)&&noCopy.Apply(1)&&noCopy.Status()==BuildState::Ready);CheckException(true);CheckException(false);
