  std::promise<void> aStarted,bStarted,releaseA,releaseB;auto fa=aStarted.get_future(),fb=bStarted.get_future();auto ra=releaseA.get_future().share(),rb=releaseB.get_future().share();std::atomic<int> active{},maximum{};auto update=[&]{int value=++active,current=maximum.load();while(value>current&&!maximum.compare_exchange_weak(current,value)){};};Coordinator stale([&](const DecodedPcm&p,std::string*e){update();if(p.frames==3){aStarted.set_value();ra.wait();}else{bStarted.set_value();rb.wait();}--active;return BuildPeakCache(p,64,e);});auto a=std::make_shared<const DecodedPcm>(Pcm(3));auto b=std::make_shared<const DecodedPcm>(Pcm(7));stale.Begin(a,1);CHECK(fa.wait_for(kTimeout)==std::future_status::ready);stale.Invalidate(2);stale.Begin(b,2);releaseA.set_value();CHECK(fb.wait_for(kTimeout)==std::future_status::ready);releaseB.set_value();CHECK(stale.WaitForCompletion(2,kTimeout)&&stale.Apply(2));CHECK(stale.Cache()&&stale.Cache()->frames==7&&maximum==1);stale.Invalidate(3);CHECK(stale.Status()==BuildState::Empty&&!stale.Cache()&&stale.Diagnostic().empty());
  // Latest-wins: B is replaced before A unblocks; C must execute and become current.
  std::promise<void> firstStarted,cStarted,releaseFirst,releaseC;auto ff=firstStarted.get_future(),fc=cStarted.get_future();auto rf=releaseFirst.get_future().share(),rc=releaseC.get_future().share();std::atomic<int> latestActive{},latestMaximum{};Coordinator latest([&](const DecodedPcm&p,std::string*e){int v=++latestActive,old=latestMaximum.load();while(v>old&&!latestMaximum.compare_exchange_weak(old,v)){};if(p.frames==3){firstStarted.set_value();rf.wait();}else{cStarted.set_value();rc.wait();}--latestActive;return BuildPeakCache(p,64,e);});auto c=std::make_shared<const DecodedPcm>(Pcm(11));latest.Begin(a,1);CHECK(ff.wait_for(kTimeout)==std::future_status::ready);latest.Begin(b,2);latest.Begin(c,3);releaseFirst.set_value();CHECK(fc.wait_for(kTimeout)==std::future_status::ready);releaseC.set_value();CHECK(latest.WaitForCompletion(3,kTimeout)&&latest.Apply(3));CHECK(latest.Cache()&&latest.Cache()->frames==11&&latestMaximum==1);
